from lib import *
S = SS('w7')
steps = [
    step("ifconfig en0 的每个字段:flags=8863<UP,BROADCAST,SMART,RUNNING,SIMPLEX,MULTICAST>——十六进制 0x8863 按位拆开正好是 0x1(UP)+ 0x2(BROADCAST)+ 0x20(SMART)+ 0x40(RUNNING)+ 0x800(SIMPLEX)+ 0x8000(MULTICAST),和尖括号里的名字一一对应;mtu 1500;options 是网卡卸载能力(TSO4/TSO6 分段卸载、PARTIAL_CSUM 校验和卸载等);inet6 是链路本地地址(%en0 是作用域,scopeid 0xe);inet 是 IPv4 地址、netmask 0xfffffc00、广播地址;status: active 表示链路是通的。UP 是管理上启用,RUNNING 是链路层有载波,两者不是一回事。", t=tl(S(1)), mark=lidx(S(1), 'flags=0x8863', 'en0: flags'), done=lidx(S(1), 'inet6', 'options=', 'status: active'), b=bars([['UP', 1, '0x1'], ['BROADCAST', 2, '0x2'], ['SMART', 32, '0x20'], ['RUNNING', 64, '0x40'], ['SIMPLEX', 2048, '0x800'], ['MULTICAST', 32768, '0x8000']], 32768, mark=[3], done=[0, 1, 2, 4, 5]), kv=KV([['flags 0x8863', '6 个标志位相加'], ['UP vs RUNNING', '管理启用 vs 链路有载波'], ['options', '网卡卸载能力(TSO、校验和)']], ['UP vs RUNNING'])),
    step("十六进制子网掩码怎么读:netmask 0xfffffc00 = 255.255.252.0 = /22(32 位里前 22 位是 1、后 10 位是 0)。网络号 = 地址 AND 掩码;广播地址 = 网络号 OR (NOT 掩码)——用本机地址算出的广播地址和 ifconfig 给的相同;这个网络共 1024 个地址,可用主机 1022 个(去掉全 0 的网络号和全 1 的广播地址)。拿一个示例 10.1.2.200/22 演示:网络号 10.1.0.0、广播 10.1.3.255、地址范围 10.1.0.1 ~ 10.1.3.254、可用主机 1022 个——/22 比我们习惯的 /24 多了两位,覆盖 4 个连续的 /24。两台主机 AND 掩码后网络号相同才被当作“直连”。", t=tl(S(2)), mark=lidx(S(2), '掩码 0x', '对照一个示例'), done=lidx(S(2), '网络号 =', '广播地址', '本机地址落在'), b=bars([['网络总地址数', 1024, '1024'], ['可用主机数', 1022, '1022']], 1024, mark=[1], done=[0]), kv=KV([['/22', '前 22 位网络、后 10 位主机'], ['可用主机', '2^10 − 2 = 1022'], ['网络号', '地址 AND 掩码']], ['/22'])),
    step("这台机器有 23 个网络接口:en×7、utun×4、anpi×3,以及 lo、gif、stf、bridge、ap、awdl、llw、pktap、nan 各 1 个。networksetup 告诉你:en0 是 Wi-Fi,en1~en3 是雷电网口,en4~en6 是以太网适配器,bridge0 是雷电网桥;utun 是用户态隧道(VPN、系统服务),awdl 是 AirDrop 用的 Apple 无线直连,gif / stf 是通用隧道与 6to4,pktap 是抓包用的伪接口。真正 UP 且有 IPv4 地址的只有 lo0 和 en0——其余要么只有 IPv6 链路本地、要么没 UP。", t=tl(S(3)), mark=lidx(S(3), 'UP 且有 IPv4', '接口 23 个'), done=lidx(S(3), '    en ', '    utun', 'lo     '), b=bars([['en', 7, '7'], ['utun', 4, '4'], ['anpi', 3, '3'], ['其它各 1 个', 9, '9 种']], 9, mark=[3], done=[0, 1, 2]), kv=KV([['接口总数', '23'], ['有 IPv4 且 UP', 'lo0、en0'], ['en0', 'Wi-Fi(networksetup)']], ['有 IPv4 且 UP'])),
    step("每个接口的收发计数(netstat -I en0 -b):Ipkts / Ierrs / Ibytes / Opkts / Oerrs / Obytes / Coll。en0 的三行共用同一组计数:第一行是链路层(<Link#14> 加 MAC),后两行是该接口的 IPv6 链路本地地址和 IPv4 网络(/22)——计数属于整个接口,地址只是在这个接口上多出来的行。收到 92164107 个包、65511630277 字节,发出 52187398 个包,Ierrs 和 Oerrs 都是 0。lo0 的收发包数相同(143749654 / 143749654),因为每个包都是自己发给自己。", t=tl(S(4)), mark=lidx(S(4), 'en0        1500  <Link#14>', 'lo0        16384'), done=lidx(S(4), 'Name'), b=bars([['en0 收到 Ibytes', 65511630277, '65.5 GB'], ['en0 发出 Obytes', 11132179573, '11.1 GB']], 65511630277, mark=[0], done=[1]), kv=KV([['en0 收 / 发包', '92164107 / 52187398'], ['错误', 'Ierrs 0 / Oerrs 0'], ['lo0', '收 = 发(自己发给自己)']], ['lo0'])),
    step("一个接口可以有多个地址:lo0 有 1 个 IPv4(127.0.0.1)和 2 个 IPv6(::1、fe80::1);en0 有 1 个 IPv4 和 1 个 IPv6;utun0 和 awdl0 没有 IPv4、只有 1 个 IPv6;bridge0 没有任何地址。大多数 UP 的接口会有一个 IPv6 链路本地地址(fe80::/10),bridge0 这种没被配置的是例外。IPv4 的 169.254.x.x 是没有 DHCP 时的自分配地址(见 DHCP / 特殊地址两篇)。用 ifconfig 接口 alias 给一个接口加多个 IPv4 需要 root,这里没有做。", t=tl(S(5)), mark=lidx(S(5), 'lo0:', 'en0:'), done=lidx(S(5), 'utun0:', 'awdl0:', 'bridge0:'), b=bars([['lo0 IPv6 地址', 2, '2'], ['en0 IPv4 地址', 1, '1'], ['bridge0 地址', 0, '0']], 2, mark=[0], done=[1, 2]), kv=KV([['lo0', 'IPv4 ×1,IPv6 ×2'], ['en0', 'IPv4 ×1,IPv6 ×1'], ['bridge0', '无地址']], ['bridge0'])),
]
